const routes={home,trail,practice,essay,errors,progress,finalReview,beforeTest,socioPage,simulation,challenge,library};
function go(name,arg){(routes[name]||home)(arg);window.scrollTo({top:0,behavior:'smooth'});$('#nav').classList.remove('open')}
